const nav = [{ label: 'Apprendre', icon: Network }, { label: 'Expérimenter', icon: Code2 }, { label: 'Visualiser le modèle', icon: Activity }, { label: 'Vérifier mes connaissances', icon: CircleHelp }]

function Metric({ label, value, tone = 'blue' }: { label: string; value: string; tone?: string }) {
  const t = useTranslation()

  const toneClasses = ({ blue: 'bg-blue-50/60 text-blue-800', violet: 'bg-violet-50/60 text-violet-800', orange: 'bg-orange-50/60 text-orange-800', emerald: 'bg-emerald-50/60 text-emerald-800' } as Record<string, string>)[tone] ?? 'bg-slate-50 text-slate-800'
  return <div className={`rounded-xl border p-3 ${toneClasses}`}><p className="text-xs font-semibold">{t(label)}</p><p className="mt-1 font-mono text-lg font-semibold">{value}</p></div>
}

function NetworkDiagram({ state }: { state: ReturnType<typeof trainLinear>[number] }) {
  const t = useTranslation()

  const active = state.step > 0
  const error = state.prediction - state.target
  return <div dir="ltr" className="relative overflow-hidden rounded-2xl border bg-slate-950 px-5 py-7 text-white shadow-inner">
    <div className="absolute inset-0 bg-[radial-gradient(circle_at_30%_20%,rgba(59,130,246,.18),transparent_32%),radial-gradient(circle_at_75%_80%,rgba(139,92,246,.15),transparent_35%)]" />
    <div className="relative flex items-center justify-between gap-3 sm:gap-7">
      <div className="z-10 flex flex-col items-center gap-2"><div className={`grid size-16 place-items-center rounded-full border-2 border-blue-400 bg-blue-500/20 font-mono text-lg ${active ? 'shadow-[0_0_24px_rgba(96,165,250,.7)]' : ''}`}>x</div><span className="text-xs text-slate-300">{t("entrée = ")}{format(state.x)}</span></div>
      <div className="relative min-w-16 flex-1"><div className="h-1 rounded-full bg-blue-400/70" /><div className="absolute -top-6 left-1/2 -translate-x-1/2 rounded bg-slate-800 px-2 py-1 font-mono text-xs text-blue-200">w = {format(state.w)}</div><ArrowRight className="absolute -right-2 -top-2 text-blue-300" /></div>
      <div className="z-10 flex flex-col items-center gap-2"><div className="grid size-16 place-items-center rounded-full border-2 border-violet-400 bg-violet-500/20 font-mono text-lg">Σ</div><span className="text-xs text-slate-300">+ b = {format(state.b)}</span></div>
      <div className="relative min-w-10 flex-1"><div className="h-1 rounded-full bg-violet-400/70" /><ArrowRight className="absolute -right-2 -top-2 text-violet-300" /></div>
      <div className="z-10 flex flex-col items-center gap-2"><div className={`grid size-16 place-items-center rounded-full border-2 border-emerald-400 bg-emerald-500/20 font-mono text-lg ${active ? 'shadow-[0_0_24px_rgba(52,211,153,.6)]' : ''}`}>{format(state.prediction)}</div><span className="text-xs text-slate-300">{t("prédiction")}</span></div>
    </div>
    <div className="relative mt-8 flex items-center justify-center gap-3 text-xs text-slate-300"><ArrowDown className="text-orange-300" /><span>{t("erreur = ")}{format(error)}{t(" · perte = ")}{format(state.loss)}{t(" · gradient w = ")}{format(state.gradW)}{t(" · gradient b = ")}{format(state.gradB)}</span></div>
  </div>
}

function ManualActivity({ onContinue, onRestart, language }: { onContinue: () => void; onRestart: () => void; language: Language }) {
  const t = useTranslation()

  const [step, setStep] = useState(0)
  const [exerciseVersion, setExerciseVersion] = useState(0)
  const nn = useMemo(() => manualNetwork(exerciseVersion), [exerciseVersion])
  const [answers, setAnswers] = useState<Record<number, string>>({})
  const localizedStepCopy: Record<Language, { titles: string[]; descriptions: string[]; prompts: string[]; answer: string }> = {
    fr: { titles: ['Propagation avant', 'Calculer la perte', 'Rétropropagation', 'Descente de gradient', 'Vérifier le résultat'], descriptions: ['Calcule chaque valeur dans l’ordre : d’abord la combinaison, puis la sigmoïde, puis la prédiction.', 'Compare la prédiction à la cible y = 1. La perte mesure l’écart au carré.', 'Utilise la règle de chaîne pour calculer les gradients qui indiquent comment réduire la perte.', 'Mets à jour les paramètres avec nouveau = ancien − η × gradient, en utilisant η = 0,1.', 'Compare les valeurs avant et après la mise à jour pour vérifier que le calcul est cohérent.'], prompts: ['Avec w₁ = {a}, x = {b} et b₁ = {c}, quelle est la valeur de z₁ ?', 'Avec ŷ = {a} et y = 1, combien vaut L = ½(ŷ − y)² ?', 'Sachant que ∂L/∂ŷ = {a} et h = {b}, combien vaut ∂L/∂w₂ = (∂L/∂ŷ) × h ?', 'Avec w₂ = {b} et ∂L/∂w₂ = {a}, quel est le nouveau w₂ ?', 'Après la mise à jour, combien vaut la nouvelle prédiction ŷ ?'], answer: 'Choisis la bonne réponse avant de continuer' },
    en: { titles: ['Forward pass', 'Calculate the loss', 'Backpropagation', 'Gradient descent', 'Check the result'], descriptions: ['Calculate each value in order: first the weighted sum, then the sigmoid, then the prediction.', 'Compare the prediction with target y = 1. The loss measures the squared difference.', 'Use the chain rule to calculate gradients that show how to reduce the loss.', 'Update the parameters with new = old − η × gradient, using η = 0.1.', 'Compare the values before and after the update to check that the calculation is consistent.'], prompts: ['With w₁ = {a}, x = {b}, and b₁ = {c}, what is z₁?', 'Given ŷ = {a} and y = 1, what is L = ½(ŷ − y)²?', 'Given ∂L/∂ŷ = {a} and h = {b}, what is ∂L/∂w₂ = (∂L/∂ŷ) × h?', 'Given w₂ = {b} and ∂L/∂w₂ = {a}, what is the new w₂?', 'After the update, what is the new prediction ŷ?'], answer: 'Choose the correct answer before continuing' },
    es: { titles: ['Propagación hacia delante', 'Calcular la pérdida', 'Retropropagación', 'Descenso del gradiente', 'Comprobar el resultado'], descriptions: ['Calcula cada valor en orden: primero la suma ponderada, después la sigmoide y, por último, la predicción.', 'Compara la predicción con el objetivo y = 1. La pérdida mide la diferencia al cuadrado.', 'Usa la regla de la cadena para calcular los gradientes que indican cómo reducir la pérdida.', 'Actualiza los parámetros con nuevo = anterior − η × gradiente, usando η = 0,1.', 'Compara los valores antes y después de la actualización para comprobar el cálculo.'], prompts: ['Con w₁ = {a}, x = {b} y b₁ = {c}, ¿cuánto vale z₁?', 'Con ŷ = {a} e y = 1, ¿cuánto vale L = ½(ŷ − y)²?', 'Si ∂L/∂ŷ = {a} y h = {b}, ¿cuánto vale ∂L/∂w₂ = (∂L/∂ŷ) × h?', 'Con w₂ = {b} y ∂L/∂w₂ = {a}, ¿cuál es el nuevo w₂?', 'Después de la actualización, ¿cuál es la nueva predicción ŷ?'], answer: 'Elige la respuesta correcta antes de continuar' },
    ar: { titles: ['التمرير الأمامي', 'حساب الخسارة', 'الانتشار العكسي', 'الانحدار المتدرج', 'تحقق من النتيجة'], descriptions: ['احسب كل قيمة بالترتيب: المجموع الموزون، ثم دالة سيغمويد، ثم التنبؤ.', 'قارن التنبؤ بالهدف y = 1. تقيس الخسارة مربع الفرق.', 'استخدم قاعدة السلسلة لحساب التدرجات التي توضح كيفية تقليل الخسارة.', 'حدّث المعلمات باستخدام الجديد = القديم − η × التدرج، حيث η = 0.1.', 'قارن القيم قبل التحديث وبعده للتحقق من اتساق الحساب.'], prompts: ['إذا كان w₁ = {a} وx = {b} وb₁ = {c}، فما قيمة z₁؟', 'إذا كانت ŷ = {a} وy = 1، فما قيمة L = ½(ŷ − y)²؟', 'إذا كان ∂L/∂ŷ = {a} وh = {b}، فما قيمة ∂L/∂w₂ = (∂L/∂ŷ) × h؟', 'إذا كان w₂ = {b} و∂L/∂w₂ = {a}، فما قيمة w₂ الجديدة؟', 'ما قيمة التنبؤ ŷ الجديدة بعد التحديث؟'], answer: 'اختر الإجابة الصحيحة قبل المتابعة' },
    hi: { titles: ['फॉरवर्ड पास', 'लॉस की गणना', 'बैकप्रोपेगेशन', 'ग्रेडिएंट डिसेंट', 'परिणाम जाँचें'], descriptions: ['हर मान क्रम से निकालें: पहले भारित योग, फिर सिग्मॉइड, फिर अनुमान।', 'अनुमान की तुलना लक्ष्य y = 1 से करें। लॉस वर्ग अंतर मापता है।', 'लॉस घटाने वाले ग्रेडिएंट निकालने के लिए चेन रूल का उपयोग करें।', 'η = 0.1 रखते हुए नया = पुराना − η × ग्रेडिएंट से पैरामीटर अपडेट करें।', 'गणना जाँचने के लिए अपडेट से पहले और बाद के मानों की तुलना करें।'], prompts: ['w₁ = {a}, x = {b} और b₁ = {c} होने पर z₁ कितना है?', 'ŷ = {a} और y = 1 होने पर L = ½(ŷ − y)² कितना है?', '∂L/∂ŷ = {a} और h = {b} होने पर ∂L/∂w₂ = (∂L/∂ŷ) × h कितना है?', 'w₂ = {b} और ∂L/∂w₂ = {a} होने पर नया w₂ क्या है?', 'अपडेट के बाद नया अनुमान ŷ कितना है?'], answer: 'आगे बढ़ने से पहले सही उत्तर चुनें' },
    tr: { titles: ['İleri yayılım', 'Kaybı hesapla', 'Geri yayılım', 'Gradyan inişi', 'Sonucu kontrol et'], descriptions: ['Her değeri sırayla hesapla: önce ağırlıklı toplamı, sonra sigmoid işlevini, ardından tahmini.', 'Tahmini y = 1 hedefiyle karşılaştır. Kayıp, farkın karesini ölçer.', 'Kaybı azaltmaya yardımcı gradyanları hesaplamak için zincir kuralını kullan.', 'η = 0,1 ile yeni = eski − η × gradyan formülünü kullanarak parametreleri güncelle.', 'Hesabın tutarlı olduğunu doğrulamak için güncelleme öncesi ve sonrası değerleri karşılaştır.'], prompts: ['w₁ = {a}, x = {b} ve b₁ = {c} ise z₁ kaçtır?', 'ŷ = {a} ve y = 1 ise L = ½(ŷ − y)² kaçtır?', '∂L/∂ŷ = {a} ve h = {b} ise ∂L/∂w₂ = (∂L/∂ŷ) × h kaçtır?', 'w₂ = {b} ve ∂L/∂w₂ = {a} ise yeni w₂ kaçtır?', 'Güncellemeden sonra yeni tahmin ŷ kaçtır?'], answer: 'Devam etmeden önce doğru yanıtı seç' },
    pt: { titles: ['Propagação direta', 'Calcular a perda', 'Retropropagação', 'Descida do gradiente', 'Verificar o resultado'], descriptions: ['Calcula cada valor por ordem: primeiro a soma ponderada, depois a sigmoide e, por fim, a previsão.', 'Compara a previsão com o alvo y = 1. A perda mede a diferença ao quadrado.', 'Usa a regra da cadeia para calcular os gradientes que indicam como reduzir a perda.', 'Atualiza os parâmetros com novo = antigo − η × gradiente, usando η = 0,1.', 'Compara os valores antes e depois da atualização para verificar se o cálculo está coerente.'], prompts: ['Com w₁ = {a}, x = {b} e b₁ = {c}, quanto vale z₁?', 'Com ŷ = {a} e y = 1, quanto vale L = ½(ŷ − y)²?', 'Sabendo que ∂L/∂ŷ = {a} e h = {b}, quanto vale ∂L/∂w₂ = (∂L/∂ŷ) × h?', 'Com w₂ = {b} e ∂L/∂w₂ = {a}, qual é o novo w₂?', 'Após a atualização, quanto vale a nova previsão ŷ?'], answer: 'Escolhe a resposta correta antes de continuar' },
  }
  const steps = [
    { title: 'Propagation avant', text: 'Calcule chaque valeur dans l’ordre : d’abord la combinaison, puis la sigmoïde, puis la prédiction.', values: [['z₁ = w₁ × x + b₁', `${format(nn.w1)} × 2 + ${format(nn.b1)}`], ['h = sigmoid(z₁)', format(nn.h)], ['ŷ = w₂ × h + b₂', format(nn.prediction)]], question: `Avec w₁ = ${format(nn.w1)}, x = ${nn.x} et b₁ = ${format(nn.b1)}, quelle est la valeur de z₁ ?`, options: [`z₁ = ${format(nn.z1)}`, `z₁ = ${format(nn.w1)}`, `z₁ = ${format(nn.w1 * nn.x + 1)}`], answer: 0 },
    { title: 'Calculer la perte', text: 'Compare la prédiction à la cible y = 1. La perte mesure l’écart au carré.', values: [['ŷ', format(nn.prediction)], ['y', format(nn.target)], ['ŷ − y', format(nn.prediction - nn.target)]], question: `Avec ŷ = ${format(nn.prediction)} et y = 1, combien vaut L = ½(ŷ − y)² ?`, options: [`L = ${format(nn.loss)}`, `L = ${format(Math.abs(nn.prediction - nn.target))}`, `L = ${format(nn.prediction + nn.target)}`], answer: 0 },
    { title: 'Rétropropagation', text: 'Utilise la règle de chaîne pour calculer les gradients qui indiquent comment réduire la perte.', values: [['∂L/∂ŷ = ŷ − y', format(nn.prediction - nn.target)], ['∂L/∂w₂', format(nn.dw2)], ['∂L/∂w₁', format(nn.dw1)], ['∂L/∂b₁', format(nn.db1)]], question: `Sachant que ∂L/∂ŷ = ${format(nn.prediction - nn.target)} et h = ${format(nn.h)}, combien vaut ∂L/∂w₂ = (∂L/∂ŷ) × h ?`, options: [`∂L/∂w₂ = ${format(nn.dw2)}`, '∂L/∂w₂ = 0,1966', '∂L/∂w₂ = 0,7311'], answer: 0 },
    { title: 'Descente de gradient', text: 'Mets à jour les paramètres avec nouveau = ancien − η × gradient, en utilisant η = 0,1.', values: [['w₁ →', `${format(nn.w1)} → ${format(nn.updated.w1)}`], ['b₁ →', `${format(nn.b1)} → ${format(nn.updated.b1)}`], ['w₂ →', `${format(nn.w2)} → ${format(nn.updated.w2)}`], ['b₂ →', `${format(nn.b2)} → ${format(nn.updated.b2)}`]], question: `Avec w₂ = ${format(nn.w2)} et ∂L/∂w₂ = ${format(nn.dw2)}, quel est le nouveau w₂ ?`, options: [`w₂ = ${format(nn.updated.w2)}`, 'w₂ = 0,9803', 'w₂ = {b},1966'], answer: 0 },
    { title: 'Vérifier le résultat', text: 'Compare les valeurs avant et après la mise à jour pour vérifier que le calcul est cohérent.', values: [['ancienne prédiction', format(nn.prediction)], ['nouvelle prédiction', format(nn.newPrediction)], ['ancienne perte', format(nn.loss)], ['nouvelle perte', format(nn.newLoss)]], question: `Après la mise à jour, combien vaut la nouvelle prédiction ŷ ?`, options: [`ŷ = ${format(nn.newPrediction)}`, 'ŷ = 0,7311', 'ŷ = 1,1058'], answer: 0 },
  ]
  const [optionOrders, setOptionOrders] = useState(() => steps.map((item) => item.options.map((_, index) => index)))
  useEffect(() => {
    setOptionOrders(steps.map((item) => {
      const order = item.options.map((_, index) => index)
      for (let index = order.length - 1; index > 0; index -= 1) {
        const randomIndex = Math.floor(Math.random() * (index + 1))
        ;[order[index], order[randomIndex]] = [order[randomIndex], order[index]]
      }
      return order
    }))
  }, [exerciseVersion])
  const currentStep = steps[step]
  const order = optionOrders[step]
  const localized = localizedStepCopy[language]
  const promptValues = step === 0 ? [format(nn.w1), String(nn.x), format(nn.b1)] : step === 1 ? [format(nn.prediction)] : step === 2 ? [format(nn.prediction - nn.target), format(nn.h)] : step === 3 ? [format(nn.dw2), format(nn.w2)] : []
  const question = interpolate(localized.prompts[step], { a: promptValues[0] ?? '', b: promptValues[1] ?? '', c: promptValues[2] ?? '' })
  const current = { ...currentStep, title: localized.titles[step], text: localized.descriptions[step], question, options: order.map(index => currentStep.options[index]), answer: order.indexOf(currentStep.answer) }
  const selectedAnswer = answers[step]
  const correctOption = currentStep.options[currentStep.answer]
  const isCorrect = selectedAnswer === correctOption
  const choose = (option: string) => setAnswers(previous => ({ ...previous, [step]: option }))
  const nextStep = () => {
    if (isCorrect) setStep(currentStepIndex => Math.min(4, currentStepIndex + 1))
  }
  return <section id="learn" className="scroll-mt-6 space-y-5">
    <div className="flex items-start justify-between gap-4"><div><Badge className="mb-3 bg-blue-100 text-blue-700 hover:bg-blue-100">{t("ACTIVITÉ 1 · PAS À PAS")}</Badge><h2 className="text-2xl font-bold tracking-tight text-slate-950 sm:text-3xl">{t("Apprends à un réseau à corriger ses erreurs")}</h2><p className="mt-2 max-w-2xl text-muted-foreground">{t("Pars d’un exemple minuscule, suis chaque opération, puis observe la mise à jour des quatre paramètres.")}</p></div><div className="hidden rounded-full bg-blue-50 p-3 text-blue-600 sm:block"><GitBranch /></div></div>
    <div className="grid gap-5 lg:grid-cols-[.9fr_1.1fr]">
      <Card className="border-slate-200 shadow-sm"><CardHeader><CardTitle className="flex items-center gap-2 text-base"><Network className="text-blue-600" />{t(" Le réseau de départ")}</CardTitle><CardDescription>{t("Paramètres : x = 2 · cible y = 1 · η = 0,1")}</CardDescription></CardHeader><CardContent className="space-y-4"><div className="rounded-xl border border-blue-100 bg-blue-50/60 p-3 font-mono text-sm leading-7 text-slate-700"><p><strong>{t("Propagation :")}</strong> z = w × x + b</p><p><strong>{t("Perte :")}</strong> L = ½(prediction − y)²</p><p><strong>{t("Mise à jour :")}</strong>{t(" nouveau = ancien − η × gradient")}</p></div><div dir="ltr" className="overflow-x-auto rounded-xl bg-slate-950 p-4 font-mono text-sm leading-8 text-slate-100">
        <p>{t("x = ")}{format(nn.x)} → z₁ = {format(nn.z1)}</p>
        <p>h = sigmoid(z₁) = {format(nn.h)}</p>
        <p>ŷ = w₂ × h + b₂ = {format(nn.prediction)}</p>
        <p>L = ½(ŷ − y)² = {format(nn.loss)}</p>
      </div><div className="grid grid-cols-2 gap-2 text-sm"><Metric label={t("w₁ · poids caché")} value={format(nn.w1)} /><Metric label={t("w₂ · poids sortie")} value={format(nn.w2)} tone="violet" /><Metric label={t("b₁ · biais caché")} value={format(nn.b1)} tone="orange" /><Metric label={t("b₂ · biais sortie")} value={format(nn.b2)} tone="emerald" /></div></CardContent></Card>
      <Card className="overflow-hidden border-violet-200 bg-white text-slate-950 shadow-md shadow-violet-950/5"><CardHeader className="border-b border-violet-100 bg-gradient-to-r from-violet-50 via-white to-blue-50 text-slate-950"><div className="flex items-center justify-between"><CardTitle className="text-base text-slate-950">{language === 'fr' ? 'Étape' : language === 'en' ? 'Step' : language === 'es' ? 'Paso' : language === 'ar' ? 'الخطوة' : language === 'hi' ? 'चरण' : language === 'tr' ? 'Adım' : 'Passo'} {step + 1} / 5 → {t(current.title)}</CardTitle><Badge className="border-violet-200 bg-white text-violet-800 hover:bg-white">η = 0,1</Badge></div><Progress value={(step + 1) * 20} className="mt-3" /></CardHeader><CardContent className="space-y-5 bg-white pt-5"><p className="text-sm leading-6 text-muted-foreground">{t(current.text)}</p><div className="space-y-2">{current.values.map(([label, value], index) => <div key={label} className={`flex items-center justify-between rounded-lg border px-3 py-3 ${step === 2 && index === 0 ? 'border-violet-300 bg-violet-50' : 'border-slate-200 bg-slate-50/80'}`}><span className="font-mono text-sm text-slate-700">{t(label)}</span><span className="font-mono text-sm font-semibold text-slate-950">{value}</span></div>)}</div><div className="rounded-xl border border-violet-200 bg-gradient-to-br from-violet-50 to-indigo-50/60 p-4"><p className="mb-2 text-sm font-semibold text-violet-950">{t(current.question)}</p><p className="mb-3 text-xs font-medium text-slate-600">{localized.answer}</p><div className="grid gap-2">{current.options.map((option, index) => <Button key={option} type="button" variant={selectedAnswer === option ? (isCorrect ? 'default' : 'destructive') : 'outline'} className={`h-auto justify-start whitespace-normal py-2.5 text-left transition-colors ${selectedAnswer === option && isCorrect ? 'border-violet-700 bg-violet-700 text-white hover:bg-violet-800 hover:text-white' : selectedAnswer === option ? '' : 'border-violet-200 bg-white text-slate-800 hover:border-violet-500 hover:bg-violet-100 hover:text-violet-950'}`} onClick={() => choose(option)}>{selectedAnswer === option && isCorrect && <Check data-icon="inline-start" />}{t(option)}</Button>)}</div>{selectedAnswer !== undefined && <p className={`mt-3 text-sm font-medium ${isCorrect ? 'text-emerald-700' : 'text-rose-700'}`}>{t(isCorrect ? 'Bonne réponse. Tu peux avancer.' : 'Ce n’est pas encore la bonne réponse, réessaie.')}</p>}</div><div className="flex items-center justify-between gap-3"><Button variant="outline" className="border-violet-200 bg-white text-violet-800 hover:border-violet-300 hover:bg-violet-50 disabled:border-violet-100 disabled:bg-violet-50 disabled:text-violet-400 disabled:opacity-100" onClick={() => setStep(Math.max(0, step - 1))} disabled={step === 0}><ChevronLeft data-icon="inline-start" />{t("Précédent")}</Button>{step < 4 ? <Button onClick={nextStep} disabled={!isCorrect}>{t("Étape suivante")}<ChevronRight data-icon="inline-end" /></Button> : <div className="flex flex-wrap justify-end gap-2"><Button variant="outline" onClick={() => { setExerciseVersion(version => version + 1); setStep(0); setAnswers({}); onRestart() }}>{language === 'fr' ? 'Faire un autre exercice' : language === 'en' ? 'Try another exercise' : language === 'es' ? 'Hacer otro ejercicio' : language === 'ar' ? 'تمرين آخر' : language === 'hi' ? 'एक और अभ्यास करें' : language === 'tr' ? 'Başka bir egzersiz' : 'Fazer outro exercício'}</Button><Button onClick={onContinue} disabled={!isCorrect} className="bg-violet-700 hover:bg-violet-800">{t("Passer à l’expérience Python")}<ArrowRight data-icon="inline-end" /></Button></div>}</div></CardContent></Card>
    </div>
    <Alert className="border-violet-200 bg-violet-50 text-slate-900 shadow-sm"><Lightbulb className="text-violet-600" /><AlertTitle className="text-violet-950">{language === 'fr' ? 'Le fil rouge' : language === 'en' ? 'The big picture' : language === 'es' ? 'La idea principal' : language === 'ar' ? 'الفكرة العامة' : language === 'hi' ? 'मुख्य विचार' : language === 'tr' ? 'Genel bakış' : 'Visão geral'}</AlertTitle><AlertDescription className="text-slate-700">{language === 'fr' ? 'Propagation avant → perte → rétropropagation → mise à jour. Dans l’activité suivante, le modèle est plus simple pour isoler exactement ce mécanisme.' : language === 'en' ? 'Forward pass → loss → backpropagation → parameter update. In the next activity, a simpler model isolates this mechanism.' : language === 'es' ? 'Propagación hacia delante → pérdida → retropropagación → actualización. En la siguiente actividad, un modelo más sencillo aísla este mecanismo.' : language === 'ar' ? 'التمرير الأمامي ← الخسارة ← الانتشار العكسي ← تحديث المعلمات. يعزل نموذج أبسط هذه الآلية في النشاط التالي.' : language === 'hi' ? 'फॉरवर्ड पास → लॉस → बैकप्रोपेगेशन → पैरामीटर अपडेट। अगली गतिविधि में सरल मॉडल इस प्रक्रिया को अलग करके दिखाता है।' : language === 'tr' ? 'İleri yayılım → kayıp → geri yayılım → parametre güncellemesi. Sonraki etkinlikte daha basit bir model bu mekanizmayı tek başına gösterir.' : 'Propagação direta → perda → retropropagação → atualização. Na atividade seguinte, um modelo mais simples isola este mecanismo.'}</AlertDescription></Alert>
  </section>
}

function CodeLab({ onRun, unlocked, language }: { onRun: (history: History, learningRate: number) => void; unlocked: boolean; language: Language }) {
  const t = useTranslation()

  const [code, setCode] = useState(starterCode)
  const [message, setMessage] = useState('')
  const [output, setOutput] = useState('')
  const [outputTruncated, setOutputTruncated] = useState(false)
  const [running, setRunning] = useState(false)
  const [params, setParams] = useState({ x: 2, y: 1, learningRate: .1, steps: 20 })
  const words = {
    fr: { running: 'Exécution en cours…', run: 'Exécuter', output: 'Sortie Python', reset: 'Réinitialiser le code', hint: 'Indice', params: 'Paramètres du programme', sync: 'Les résultats viennent maintenant du vrai interpréteur Python.', rate: 'Taux d’apprentissage', steps: 'Étapes d’entraînement', why: 'Exécution isolée', explain: 'Python 3 s’exécute dans un bac à sable temporaire. Le temps, la mémoire et la sortie sont limités. Les variables x, y, w et b relient un entraînement au diagramme et aux graphiques.', noTrace: 'Aucun état d’entraînement x, y, w, b détecté : la sortie Python est affichée ci-dessus.', success: 'Python exécuté : les états détectés alimentent le diagramme et les graphiques.', failure: 'Impossible d’exécuter Python pour le moment.', timeout: 'Temps limite atteint (12 s). Réduis la charge de calcul et réessaie.' },
    en: { running: 'Running…', run: 'Run', output: 'Python output', reset: 'Reset code', hint: 'Hint', params: 'Program parameters', sync: 'Results now come from the Python interpreter.', rate: 'Learning rate', steps: 'Training steps', why: 'Isolated execution', explain: 'Python 3 runs in a temporary sandbox. Execution time, memory, and output are limited. Variables x, y, w, and b connect a training run to the diagram and charts.', noTrace: 'No training state with x, y, w, b was detected. Python output is shown above.', success: 'Python ran: detected states now power the diagram and charts.', failure: 'Python could not run right now.', timeout: 'Time limit reached (12 s). Reduce the workload and try again.' },
    es: { running: 'Ejecutando…', run: 'Ejecutar', output: 'Salida de Python', reset: 'Restablecer código', hint: 'Pista', params: 'Parámetros del programa', sync: 'Los resultados proceden del intérprete de Python.', rate: 'Tasa de aprendizaje', steps: 'Pasos de entrenamiento', why: 'Ejecución aislada', explain: 'Python 3 se ejecuta en un entorno temporal aislado. El tiempo, la memoria y la salida son limitados. Las variables x, y, w y b conectan el entrenamiento con el diagrama y los gráficos.', noTrace: 'No se detectaron estados de entrenamiento x, y, w, b. La salida de Python aparece arriba.', success: 'Python se ejecutó: los estados detectados alimentan el diagrama y los gráficos.', failure: 'No se pudo ejecutar Python ahora.', timeout: 'Se alcanzó el límite de 12 s. Reduce el trabajo y vuelve a intentarlo.' },
    ar: { running: 'جارٍ التنفيذ…', run: 'تشغيل', output: 'مخرجات Python', reset: 'إعادة ضبط الرمز', hint: 'تلميح', params: 'معلمات البرنامج', sync: 'تأتي النتائج الآن من مفسر Python.', rate: 'معدل التعلّم', steps: 'خطوات التدريب', why: 'تنفيذ معزول', explain: 'يعمل Python 3 في بيئة مؤقتة معزولة. توجد حدود للوقت والذاكرة والمخرجات. تربط المتغيرات x وy وw وb التدريب بالمخطط والرسوم البيانية.', noTrace: 'لم يتم العثور على حالة تدريب للمتغيرات x وy وw وb. تظهر مخرجات Python أعلاه.', success: 'تم تشغيل Python: الحالات المكتشفة تغذي المخطط والرسوم.', failure: 'تعذر تشغيل Python الآن.', timeout: 'انتهت مهلة 12 ثانية. قلل حجم العمل وحاول مجددًا.' },
    hi: { running: 'चल रहा है…', run: 'चलाएँ', output: 'Python आउटपुट', reset: 'कोड रीसेट करें', hint: 'संकेत', params: 'प्रोग्राम पैरामीटर', sync: 'परिणाम अब Python इंटरप्रेटर से आते हैं।', rate: 'लर्निंग रेट', steps: 'ट्रेनिंग चरण', why: 'अलग वातावरण में निष्पादन', explain: 'Python 3 एक अस्थायी सैंडबॉक्स में चलता है। समय, मेमोरी और आउटपुट सीमित हैं। x, y, w और b वैरिएबल प्रशिक्षण को डायग्राम और चार्ट से जोड़ते हैं।', noTrace: 'x, y, w, b वाला प्रशिक्षण नहीं मिला। Python आउटपुट ऊपर दिखाया गया है।', success: 'Python चल गया: मिले हुए स्टेट्स अब डायग्राम और चार्ट चलाते हैं।', failure: 'अभी Python नहीं चल सका।', timeout: '12 सेकंड की सीमा पूरी हुई। काम कम करके फिर प्रयास करें।' },
    tr: { running: 'Çalışıyor…', run: 'Çalıştır', output: 'Python çıktısı', reset: 'Kodu sıfırla', hint: 'İpucu', params: 'Program parametreleri', sync: 'Sonuçlar artık Python yorumlayıcısından geliyor.', rate: 'Öğrenme oranı', steps: 'Eğitim adımları', why: 'Yalıtılmış çalıştırma', explain: 'Python 3 geçici bir korumalı alanda çalışır. Süre, bellek ve çıktı sınırlıdır. x, y, w ve b değişkenleri eğitimi diyagrama ve grafiklere bağlar.', noTrace: 'x, y, w, b içeren bir eğitim durumu bulunamadı. Python çıktısı yukarıda gösteriliyor.', success: 'Python çalıştı: bulunan durumlar diyagramı ve grafikleri besliyor.', failure: 'Python şu anda çalıştırılamadı.', timeout: '12 saniyelik süre sınırına ulaşıldı. İş yükünü azaltıp yeniden deneyin.' },
    pt: { running: 'A executar…', run: 'Executar', output: 'Saída do Python', reset: 'Repor o código', hint: 'Dica', params: 'Parâmetros do programa', sync: 'Os resultados vêm agora do interpretador Python.', rate: 'Taxa de aprendizagem', steps: 'Etapas de treino', why: 'Execução isolada', explain: 'O Python 3 é executado numa área temporária isolada. O tempo, a memória e a saída são limitados. As variáveis x, y, w e b ligam o treino ao diagrama e aos gráficos.', noTrace: 'Não foi detetado um estado de treino com x, y, w, b. A saída Python aparece acima.', success: 'Python executado: os estados detetados alimentam o diagrama e os gráficos.', failure: 'Não foi possível executar Python agora.', timeout: 'Limite de 12 s atingido. Reduza a carga e tente novamente.' },
  }[language]
  const run = async () => {
    if (!unlocked || running) return
    setRunning(true)
    setMessage('')
    setOutput('')
    setOutputTruncated(false)
    try {
      const response = await fetch('/api/python', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ code }), signal: AbortSignal.timeout(55_000) })
      const result = await response.json() as { error?: string; stdout?: string; stderr?: string; truncated?: boolean; failed?: boolean; history?: History }
      if (!response.ok || result.error) {
        const sourceError = result.error ?? ''
        throw new Error(response.status === 408 ? 'Temps limite atteint (12 s). Réduis la charge de calcul et réessaie.' : sourceError || 'Impossible d’exécuter Python pour le moment.')
      }
      const nextHistory = readHistory(result.history)
      setOutput([result.stdout?.trimEnd(), result.stderr?.trimEnd() ? `stderr:\n${result.stderr.trimEnd()}` : ''].filter(Boolean).join('\n'))
      setOutputTruncated(Boolean(result.truncated))
      if (nextHistory.length > 0) {
        const last = nextHistory.at(-1)!
        const parsed = parseParameters(code)
        setParams({ x: last.x, y: last.target, learningRate: parsed.learningRate, steps: Math.max(1, nextHistory.length - 1) })
        onRun(nextHistory, parsed.learningRate)
        setMessage(result.failed ? 'Impossible d’exécuter Python pour le moment.' : 'Python exécuté : les états détectés alimentent le diagramme et les graphiques.')
      } else {
        setMessage(result.failed ? 'Impossible d’exécuter Python pour le moment.' : 'Aucun état d’entraînement x, y, w, b détecté : la sortie Python est affichée ci-dessus.')
      }
    } catch (error) {
      setMessage(error instanceof Error ? (error.name === 'TimeoutError' ? 'Temps limite atteint (12 s). Réduis la charge de calcul et réessaie.' : (error instanceof TypeError || error instanceof SyntaxError) ? 'Impossible d’exécuter Python pour le moment.' : error.message) : 'Impossible d’exécuter Python pour le moment.')
    } finally {
      setRunning(false)
    }
  }
  return <section id="experiment" className="scroll-mt-6 space-y-5"><div><Badge className="mb-3 bg-violet-100 text-violet-700 hover:bg-violet-100">{t("ACTIVITÉ 2 · SIMULATION")}</Badge> {!unlocked && <Alert className="mt-4 border-orange-200 bg-orange-50"><AlertDescription><strong>{t("Exercice verrouillé :")}</strong>{t(" tu ne peux pas faire cet exercice tant que le réseau de départ n’est pas terminé. Termine les 5 étapes et leurs réponses avant de continuer.")}</AlertDescription></Alert>}<h2 className="text-2xl font-bold tracking-tight text-slate-950 sm:text-3xl">{t("Maintenant, fais apprendre le modèle toi-même")}</h2><p className="mt-2 max-w-2xl text-muted-foreground">{t("Modifie le programme, valide tes formules et exécute du vrai code Python dans un environnement isolé.")}</p></div><Card className="overflow-hidden border-slate-200 shadow-sm"><div className="grid lg:grid-cols-[1.2fr_.8fr]"><div className="border-b bg-[#101827] p-4 lg:border-b-0 lg:border-r"><div className="mb-3 flex items-center justify-between"><div className="flex items-center gap-2 text-sm font-medium text-slate-200"><Code2 className="text-violet-300" /> exercice.py</div><Badge variant="outline" className="border-violet-400/40 bg-violet-400/10 text-violet-200">Python 3 · Vercel Sandbox</Badge></div><Textarea dir="ltr" value={code} onChange={e => { const next = e.target.value; setCode(next); const parsed = parseParameters(next); setParams({ x: parsed.x, y: parsed.y, learningRate: parsed.learningRate, steps: parsed.steps }) }} aria-label={t("Code Python de l'exercice")} className="min-h-[390px] resize-y border-slate-700 bg-slate-950 font-mono text-[13px] leading-6 text-slate-200 placeholder:text-slate-500 focus-visible:ring-violet-400" spellCheck={false} /><div className="mt-3 flex flex-wrap gap-2"><Button onClick={run} disabled={!unlocked || running} className="bg-violet-500 text-white hover:bg-violet-600"><Play data-icon="inline-start" />{running ? words.running : words.run}</Button><Button variant="outline" onClick={() => { setCode(starterCode); setParams({ x: 2, y: 1, learningRate: .1, steps: 20 }); setMessage(''); setOutput(''); setOutputTruncated(false) }} className="border-slate-600 bg-transparent text-slate-200 hover:bg-slate-800"><RotateCcw data-icon="inline-start" />{words.reset}</Button><Button variant="ghost" onClick={() => setMessage('Indice : vérifie prediction, loss, grad_w, grad_b et les deux formules de mise à jour.')} className="text-slate-300"><Lightbulb data-icon="inline-start" />{words.hint}</Button></div>{output && <div className="mt-4 rounded-xl border border-slate-700 bg-slate-950 p-3 text-slate-200"><p className="mb-2 text-xs font-semibold text-violet-300">{words.output}</p><pre dir="ltr" className="max-h-48 overflow-auto whitespace-pre-wrap break-words font-mono text-xs">{output}</pre>{outputTruncated && <p className="mt-2 text-xs text-slate-400">{t('… sortie tronquée')}</p>}</div>}</div><div className="space-y-5 p-5"><div><p className="text-sm font-semibold text-slate-900">{words.params}</p><p className="mt-1 text-xs text-muted-foreground">{words.sync}</p></div><div className="grid grid-cols-2 gap-3"><Metric label="x" value={format(params.x)} /><Metric label="y" value={format(params.y)} tone="violet" /></div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-1"><label className="grid gap-1 text-sm"><span className="text-muted-foreground">{words.rate}</span><Input type="number" min="0.001" max="2" step="0.01" value={params.learningRate} onChange={e => { const v = Number(e.target.value); if (!Number.isFinite(v) || v <= 0 || v > 2) return; setCode(c => updateCodeParameter(c, 'learning_rate', v)); setParams(p => ({ ...p, learningRate: v })) }} /></label><label className="grid gap-1 text-sm"><span className="text-muted-foreground">{words.steps}</span><Input type="number" min="1" max="100" value={params.steps} onChange={e => { const v = Number(e.target.value); if (!Number.isInteger(v) || v < 1 || v > 100) return; setCode(c => updateCodeParameter(c, 'training_steps', v)); setParams(p => ({ ...p, steps: v })) }} /></label></div>{message && <Alert className={message === 'Python exécuté : les états détectés alimentent le diagramme et les graphiques.' ? 'border-emerald-200 bg-emerald-50' : 'border-orange-200 bg-orange-50'}><AlertDescription>{t(message)}</AlertDescription></Alert>}<div className="rounded-xl bg-slate-50 p-4 text-sm leading-6 text-muted-foreground"><p className="font-medium text-slate-800">{words.why}</p><p className="mt-1">{words.explain}</p></div></div></div></Card></section>
}

function TrainingLab({ history, learningRate, setLearningRate, language }: { history: History; learningRate: number; setLearningRate: (v: number) => void; language: Language }) {
  const t = useTranslation()

  const [selected, setSelected] = useState(history.length - 1)
  const [playing, setPlaying] = useState(false)
  useEffect(() => {
    setSelected(history.length - 1)
    setPlaying(false)
  }, [history])
  useEffect(() => {
    if (!playing) return
    if (selected >= history.length - 1) { setPlaying(false); return }
    const timer = window.setTimeout(() => setSelected(index => Math.min(index + 1, history.length - 1)), 700)
    return () => window.clearTimeout(timer)
  }, [playing, selected, history.length])
  const selectedIndex = Math.min(selected, history.length - 1)
  const state = history[selectedIndex]
  const status = history.at(-1)!.loss < history[0].loss ? 'Le modèle apprend : sa prédiction se rapproche de la cible et sa perte diminue.' : 'La perte augmente : ce taux est peut-être trop élevé, le modèle dépasse la bonne direction.'
  return <section id="visualize" className="scroll-mt-6 space-y-5"><div className="flex flex-wrap items-end justify-between gap-4"><div><Badge className="mb-3 bg-orange-100 text-orange-700 hover:bg-orange-100">{t("LABORATOIRE · VUE INTERNE")}</Badge><h2 className="text-2xl font-bold tracking-tight text-slate-950 sm:text-3xl">{t("Visualise chaque mise à jour")}</h2><p className="mt-2 max-w-2xl text-muted-foreground">{t("Sélectionne un instant : le diagramme, les métriques et l’historique utilisent exactement le même état calculé.")}</p></div><div className="flex items-center gap-2 rounded-xl border bg-white p-2"><Button size="icon" variant="outline" onClick={() => setSelected(Math.max(0, selected - 1))} aria-label={t("Étape précédente")}><ChevronLeft /></Button><Button size="icon" onClick={() => { if (!playing && selectedIndex === history.length - 1) setSelected(0); setPlaying(v => !v) }} aria-label={t(playing ? 'Pause' : 'Lecture')}>{playing ? <Pause /> : <Play />}</Button><Button size="icon" variant="outline" onClick={() => setSelected(Math.min(history.length - 1, selected + 1))} aria-label={t("Étape suivante")}><ChevronRight /></Button><Button size="sm" variant="ghost" onClick={() => setSelected(0)}><RotateCcw data-icon="inline-start" />{t("Recommencer")}</Button></div></div>
    <NetworkDiagram state={state} />
    <div className="grid grid-cols-2 gap-3 sm:grid-cols-4 lg:grid-cols-8"><Metric label={t("étape")} value={`${state.step}`} tone="violet" /><Metric label={t("prédiction")} value={format(state.prediction)} tone="blue" /><Metric label={t("perte")} value={format(state.loss)} tone="orange" /><Metric label={t("erreur")} value={format(state.prediction - state.target)} tone="orange" /><Metric label={t("gradient w")} value={format(state.gradW)} tone="violet" /><Metric label={t("gradient b")} value={format(state.gradB)} tone="violet" /><Metric label={t("poids w")} value={format(state.w)} tone="emerald" /><Metric label={t("biais b")} value={format(state.b)} tone="emerald" /></div>
      <Card className="border-slate-200 shadow-sm"><CardContent className="space-y-3 pt-6"><div className="flex items-center justify-between text-sm"><span className="font-medium">{t("Étape inspectée : ")}{state.step} / {history.length - 1}</span><span className="text-muted-foreground">{t("vitesse : 0,7 s")}</span></div><Slider value={[selectedIndex]} min={0} max={Math.max(1, history.length - 1)} disabled={history.length < 2} step={1} onValueChange={v => setSelected(Array.isArray(v) ? v[0] : v)} aria-label={t("Étape d'entraînement")} /></CardContent></Card>
    <Alert className={history.at(-1)!.loss < history[0].loss ? 'border-emerald-200 bg-emerald-50' : 'border-orange-200 bg-orange-50'}><TrendingDown className="text-emerald-600" /><AlertDescription>{t(status)}</AlertDescription></Alert>
    <div className="grid gap-5 xl:grid-cols-3"><ChartCard title={t("Perte par étape")} data={history} dataKey="loss" color="var(--color-loss)" type="area" /><ChartCard title={t("Prédiction et cible")} data={history.map(s => ({ ...s, target: s.target }))} dataKey="prediction" color="var(--color-prediction)" target /><ChartCard title={t("Poids et biais")} data={history} dataKey="w" color="var(--color-weight)" bias /></div>
    <Card className="border-slate-200 shadow-sm"><CardHeader><CardTitle className="text-base">{t("Historique d’entraînement")}</CardTitle><CardDescription>{t("Clique sur une ligne pour inspecter cet état dans le réseau.")}</CardDescription></CardHeader><CardContent><div className="overflow-x-auto"><Table><TableHeader><TableRow><TableHead>{t("Étape")}</TableHead><TableHead>{t("Prédiction")}</TableHead><TableHead>{t("Perte")}</TableHead><TableHead>{t("Poids")}</TableHead><TableHead>{t("Biais")}</TableHead><TableHead>{t("Gradient w")}</TableHead></TableRow></TableHeader><TableBody>{history.filter((_, i) => i === 0 || i % 2 === 0 || i === history.length - 1).map(row => <TableRow key={row.step} aria-selected={row.step === selectedIndex} tabIndex={0} onKeyDown={event => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); setSelected(row.step) } }} className={`cursor-pointer transition-colors hover:bg-muted/50 ${row.step === selectedIndex ? 'bg-violet-100' : ''}`} style={row.step === selectedIndex ? { backgroundColor: '#ede9fe', color: '#1e1b4b', boxShadow: 'inset 4px 0 #7c3aed' } : undefined} onClick={() => setSelected(row.step)}><TableCell className="font-medium">{row.step === 0 ? t('Init.') : row.step}</TableCell><TableCell>{format(row.prediction)}</TableCell><TableCell>{format(row.loss)}</TableCell><TableCell>{format(row.w)}</TableCell><TableCell>{format(row.b)}</TableCell><TableCell className={row.step === selectedIndex ? "font-medium text-violet-900" : "text-violet-700"}>{format(row.gradW)}</TableCell></TableRow>)}</TableBody></Table></div></CardContent></Card>
    <RateComparison initial={history[0]} steps={history.length - 1} active={learningRate} onSelect={setLearningRate} language={language} />
  </section>
}

function ChartCard({ title, data, dataKey, color, type, target, bias }: { title: string; data: History | (History[number] & { target: number })[]; dataKey: string; color: string; type?: string; target?: boolean; bias?: boolean }) {
  const t = useTranslation()

  return <Card className="min-w-0 border-slate-200 shadow-sm"><CardHeader className="pb-2"><CardTitle className="text-sm">{t(title)}</CardTitle></CardHeader><CardContent className="h-56 pl-1 pr-4"><ResponsiveContainer width="100%" height="100%"><LineChart data={data}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" /><XAxis dataKey="step" tickLine={false} axisLine={false} fontSize={11} /><YAxis tickLine={false} axisLine={false} fontSize={11} width={36} /><ChartTooltip labelFormatter={step => `${t('Étape')} ${step}`} contentStyle={{ borderRadius: 10, border: '1px solid #e2e8f0', fontSize: 12 }} /><Line type="monotone" dataKey={dataKey} name={t(dataKey === 'prediction' ? 'Prédiction' : dataKey === 'loss' ? 'Perte' : 'Poids')} stroke={color} strokeWidth={2.5} dot={false} /><>{target && <Line type="monotone" dataKey="target" name={t('cible')} stroke="#94a3b8" strokeDasharray="4 4" dot={false} />}{bias && <Line type="monotone" dataKey="b" name={t('Biais')} stroke="var(--color-bias)" strokeWidth={2} dot={false} />}</></LineChart></ResponsiveContainer></CardContent></Card>
}

function RateComparison({ initial, steps, active, onSelect, language }: { initial: History[number]; steps: number; active: number; onSelect: (v: number) => void; language: Language }) {
  const t = useTranslation()

  const rates = [.01, .1, .5]
  const labels = {
    fr: ['Comparer les trois taux', 'Mêmes paramètres de départ, trois tailles de pas différentes.', 'Taux intermédiaire', 'lent', 'équilibré', 'rapide', 'perte finale :', 'échelle log₁₀', 'Un taux plus élevé n’est pas automatiquement meilleur : il peut accélérer l’apprentissage, mais aussi créer du dépassement ou de l’instabilité.'],
    en: ['Compare the three rates', 'Same starting parameters, three different step sizes.', 'Middle rate', 'slow', 'balanced', 'fast', 'final loss:', 'log₁₀ scale', 'A higher rate is not always better: it can speed up learning, but may also cause overshooting or instability.'],
    es: ['Compara las tres tasas', 'Mismos parámetros iniciales y tres tamaños de paso.', 'Tasa intermedia', 'lenta', 'equilibrada', 'rápida', 'pérdida final:', 'escala log₁₀', 'Una tasa más alta no siempre es mejor: puede acelerar el aprendizaje, pero también provocar exceso o inestabilidad.'],
    ar: ['قارن معدلات التعلّم الثلاثة', 'نفس قيم البداية وثلاثة أحجام مختلفة للخطوة.', 'المعدل المتوسط', 'بطيء', 'متوازن', 'سريع', 'الخسارة النهائية:', 'مقياس لوغاريتمي', 'المعدل الأعلى ليس أفضل دائمًا؛ قد يسرّع التعلّم أو يسبب تجاوزًا وعدم استقرار.'],
    hi: ['तीनों लर्निंग रेट की तुलना करें', 'समान शुरुआती पैरामीटर, तीन अलग-अलग कदम आकार।', 'मध्यम दर', 'धीमा', 'संतुलित', 'तेज़', 'अंतिम लॉस:', 'लॉग₁₀ पैमाना', 'ऊँची दर हमेशा बेहतर नहीं होती; इससे सीखना तेज़ हो सकता है, लेकिन अस्थिरता भी आ सकती है।'],
    tr: ['Üç öğrenme oranını karşılaştır', 'Aynı başlangıç parametreleri, üç farklı adım boyutu.', 'Orta oran', 'yavaş', 'dengeli', 'hızlı', 'son kayıp:', 'log₁₀ ölçeği', 'Daha yüksek oran her zaman daha iyi değildir; öğrenmeyi hızlandırabilir, ancak kararsızlığa da yol açabilir.'],
    pt: ['Compare as três taxas', 'Mesmos parâmetros iniciais, três tamanhos de passo.', 'Taxa intermédia', 'lenta', 'equilibrada', 'rápida', 'perda final:', 'escala log₁₀', 'Uma taxa maior nem sempre é melhor: pode acelerar a aprendizagem, mas também causar excesso ou instabilidade.'],
  }[language]
  const series = useMemo(() => rates.map(rate => ({ rate, history: trainLinear(rate, steps, initial.w, initial.b, initial.x, initial.target) })), [steps, initial])
  const chartData = Array.from({ length: steps + 1 }, (_, step) => Object.fromEntries([
    ['step', step],
    ...series.map(({ rate, history }) => [`loss-${rate}`, history[step] ? Math.log10(Math.max(history[step].loss, 1e-12)) : null]),
  ]))
  const colors = ['#64748b', '#7c3aed', '#ea580c']
  return <Card className="border-slate-200 shadow-sm"><CardHeader><div className="flex flex-wrap items-center justify-between gap-3"><div><CardTitle className="text-base">{labels[0]}</CardTitle><CardDescription>{labels[1]}</CardDescription></div><Button variant="outline" size="sm" onClick={() => onSelect(.1)}><Gauge data-icon="inline-start" />{labels[2]}</Button></div></CardHeader><CardContent><div className="grid gap-4 lg:grid-cols-[.8fr_1.2fr]"><div className="grid gap-2 sm:grid-cols-3 lg:grid-cols-1">{series.map(({ rate, history }, i) => <button key={rate} onClick={() => onSelect(rate)} aria-pressed={active === rate} className={`rounded-xl border p-3 text-left transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-violet-500 ${active === rate ? 'border-violet-800 bg-violet-700 text-white' : 'border-slate-200 bg-white text-slate-900 hover:border-violet-300 hover:bg-violet-50'}`}><div className="flex items-center justify-between gap-2"><span className="font-mono font-semibold">η = {rate}</span><Badge variant="outline" className={active === rate ? 'border-white/60 bg-white/15 text-white' : 'border-slate-300 bg-white text-slate-700'}>{labels[3 + i]}</Badge></div><p className={`mt-1 text-xs ${active === rate ? 'text-violet-100' : 'text-slate-700'}`}>{labels[6]} {history.at(-1)!.loss.toExponential(2)}</p></button>)}</div><div className="min-w-0"><p className="mb-1 text-right text-[11px] text-muted-foreground">{labels[7]}</p><div className="h-64 min-w-0"><ResponsiveContainer width="100%" height="100%"><LineChart data={chartData} margin={{ top: 8, right: 8, bottom: 4, left: 0 }}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" /><XAxis dataKey="step" type="number" domain={[0, Math.max(1, steps)]} tickLine={false} axisLine={false} fontSize={11} allowDecimals={false} /><YAxis tickLine={false} axisLine={false} fontSize={11} width={42} domain={['auto', 'auto']} ticks={[-12, -9, -6, -3, 0, 3, 6]} tickFormatter={value => `10^${value}`} /><ChartTooltip contentStyle={{ borderRadius: 10, fontSize: 12 }} labelFormatter={step => `${t('Étape')} ${step}`} formatter={(value, name) => [Number.isFinite(Number(value)) ? `10^${Number(value).toFixed(2)}` : '—', String(name).replace('loss-', 'η = ')]} />{series.map(({ rate }, i) => <Line key={rate} type="monotone" dataKey={`loss-${rate}`} name={`η = ${rate}`} stroke={colors[i]} strokeWidth={rate === active ? 3 : 2} dot={false} activeDot={{ r: 4 }} connectNulls />)}</LineChart></ResponsiveContainer></div></div></div><p className="mt-4 text-sm text-muted-foreground">{labels[8]}</p></CardContent></Card>
}

function QuizSection({ onProgress }: { onProgress: (count: number) => void }) {
  const t = useTranslation()
 const [answers, setAnswers] = useState<number[]>([]); useEffect(() => { onProgress(quiz.filter((_, index) => answers[index] !== undefined).length) }, [answers, onProgress]); const score = answers.filter((a, i) => a === quiz[i]?.answer).length; return <section id="quiz" className="scroll-mt-6 space-y-5"><div><Badge className="mb-3 bg-emerald-100 text-emerald-700 hover:bg-emerald-100">{t("ÉTAPE FINALE · QUIZ")}</Badge><h2 className="text-2xl font-bold tracking-tight text-slate-950 sm:text-3xl">{t("Vérifie tes connaissances")}</h2><p className="mt-2 max-w-2xl text-muted-foreground">{t("Cinq questions pour consolider le lien entre les calculs et l’intuition.")}</p></div><div className="grid gap-4">{quiz.map((item, i) => { const selected = answers[i]; const answered = selected !== undefined; return <Card key={item.question} className="border-slate-200 shadow-sm"><CardHeader><div className="flex items-start gap-3"><div className="grid size-8 shrink-0 place-items-center rounded-full bg-slate-100 text-sm font-semibold">{i + 1}</div><CardTitle className="text-base leading-6">{t(item.question)}</CardTitle></div></CardHeader><CardContent className="space-y-3"><div className="grid gap-2 sm:grid-cols-3">{item.options.map((option, oi) => <Button key={option} variant={selected === oi ? (oi === item.answer ? 'default' : 'destructive') : 'outline'} className={`h-auto justify-start whitespace-normal py-3 text-left ${selected === oi ? (oi === item.answer ? 'border-violet-700 bg-violet-700 text-white hover:bg-violet-800' : 'border-rose-700 bg-rose-700 text-white hover:bg-rose-800') : 'border-slate-300 bg-white text-slate-800 hover:border-violet-400 hover:bg-violet-50 hover:text-slate-950'}`} onClick={() => setAnswers(a => { const next = [...a]; next[i] = oi; return next })}>{selected === oi && oi === item.answer && <Check data-icon="inline-start" />}{t(option)}</Button>)}</div>{answered && <p className={`text-sm ${selected === item.answer ? 'text-emerald-700' : 'text-orange-700'}`}>{t(selected === item.answer ? 'Bonne réponse. ' : 'Pas tout à fait. ')}{t(item.explanation)}</p>}</CardContent></Card>})}</div>{quiz.every((_, index) => answers[index] !== undefined) && <Alert className="border-emerald-200 bg-emerald-50"><Trophy className="text-emerald-600" /><AlertDescription><strong>{t("Score : ")}{score} / {quiz.length}.</strong> {t(score >= 4 ? 'Excellent travail, les mécanismes essentiels sont en place.' : 'Relis les étapes puis essaie encore pour consolider les notions.')}</AlertDescription></Alert>}</section> }

const languageLabels = {
  fr: { learn: 'Apprendre', experiment: 'Expérimenter', visualize: 'Visualiser le modèle', quiz: 'Vérifier mes connaissances', journey: 'Parcours', session: 'Session locale', choose: 'Choisir la langue', footer: 'Exécution Python sécurisée par un bac à sable temporaire.' },
  en: { learn: 'Learn', experiment: 'Experiment', visualize: 'Visualize the model', quiz: 'Check my knowledge', journey: 'Learning path', session: 'Local session', choose: 'Choose language', footer: 'Python runs securely in a temporary sandbox.' },
  es: { learn: 'Aprender', experiment: 'Experimentar', visualize: 'Visualizar el modelo', quiz: 'Comprobar mis conocimientos', journey: 'Ruta de aprendizaje', session: 'Sesión local', choose: 'Elegir idioma', footer: 'Python se ejecuta de forma segura en un entorno temporal aislado.' },
  ar: { learn: 'تعلّم', experiment: 'تجربة', visualize: 'تصوّر النموذج', quiz: 'اختبر معرفتك', journey: 'مسار التعلّم', session: 'جلسة محلية', choose: 'اختر اللغة', footer: 'يعمل Python بأمان في بيئة مؤقتة معزولة.' },
  hi: { learn: 'सीखें', experiment: 'प्रयोग करें', visualize: 'मॉडल देखें', quiz: 'ज्ञान जाँचें', journey: 'सीखने की यात्रा', session: 'स्थानीय सत्र', choose: 'भाषा चुनें', footer: 'Python अस्थायी सैंडबॉक्स में सुरक्षित रूप से चलता है।' },
  tr: { learn: 'Öğren', experiment: 'Dene', visualize: 'Modeli görselleştir', quiz: 'Bilgimi kontrol et', journey: 'Öğrenme yolu', session: 'Yerel oturum', choose: 'Dil seç', footer: 'Python geçici bir korumalı alanda güvenle çalışır.' },
  pt: { learn: 'Aprender', experiment: 'Experimentar', visualize: 'Visualizar o modelo', quiz: 'Verificar conhecimentos', journey: 'Percurso', session: 'Sessão local', choose: 'Escolher idioma', footer: 'O Python é executado em segurança numa área temporária isolada.' },
} as const

type Language = keyof typeof languageLabels

export default function Page() {
  const [language, setLanguage] = useState<Language>('fr')
  const t = (text: string) => translate(text, language)
  useEffect(() => {
    document.documentElement.lang = language
    document.documentElement.dir = language === 'ar' ? 'rtl' : 'ltr'
  }, [language])
  const labels = languageLabels[language]
  const localizedNav = [
    { label: labels.learn, icon: Network, href: '#learn' },
    { label: labels.experiment, icon: Code2, href: '#experiment' },
    { label: labels.visualize, icon: Activity, href: '#visualize' },
    { label: labels.quiz, icon: CircleHelp, href: '#quiz' },
  ]
  const [history, setHistory] = useState(() => trainLinear(.1, 20))
  const [learningRate, setLearningRate] = useState(.1)
  const [manualDone, setManualDone] = useState(false)
  const [active, setActive] = useState('#learn')
  const run = (next: History, nextLearningRate: number) => { setHistory(next); setLearningRate(nextLearningRate); setHasRun(true); document.getElementById('visualize')?.scrollIntoView({ behavior: 'smooth' }) }
  const [quizAnswered, setQuizAnswered] = useState(0)
  const [hasRun, setHasRun] = useState(false)
  const progress = (manualDone ? 40 : 0) + (hasRun ? 30 : 0) + quizAnswered * 6
  return <TranslationProvider language={language}><main className="min-h-screen bg-[#f7f9fc] text-slate-950"><header className="sticky top-0 z-20 border-b bg-white/90 backdrop-blur"><div className="mx-auto flex max-w-[1500px] items-center justify-between gap-4 px-4 py-3 lg:px-8"><a href="#top" className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-xl bg-slate-950 text-white shadow-sm"><Sparkles /></div><div><p className="text-sm font-bold tracking-tight">Neural Network</p><p className="text-xs text-violet-600">Learning Lab</p></div></a><div className="flex items-center gap-2"><label className="flex items-center gap-1.5 rounded-lg border bg-white px-2.5 py-2 text-xs font-medium text-slate-700 shadow-sm"><Languages className="size-4 text-violet-600" /><span className="sr-only">{labels.choose}</span><select aria-label={labels.choose} value={language} onChange={event => { const next = event.target.value as Language; setLanguage(next); document.documentElement.lang = next }} className="bg-transparent outline-none"><option value="fr">Français</option><option value="en">English</option><option value="es">Español</option><option value="ar">العربية</option><option value="hi">हिन्दी</option><option value="tr">Türkçe</option><option value="pt">Português</option></select></label><div className="hidden items-center gap-2 md:flex"><Badge variant="outline" className="gap-1.5 border-emerald-200 bg-emerald-50 text-emerald-700"><span className="size-1.5 rounded-full bg-emerald-500" />{labels.session}</Badge><div className="flex items-center gap-2 text-xs text-muted-foreground"><Progress value={progress} className="w-20" />{progress}%</div></div></div></div></header><div id="top" className="mx-auto grid max-w-[1500px] lg:grid-cols-[240px_1fr]"><aside className="hidden border-r bg-white/70 px-4 py-7 lg:block"><div className="sticky top-24 space-y-6"><div><p className="mb-3 px-3 text-xs font-semibold uppercase tracking-widest text-muted-foreground">{labels.journey}</p><nav className="grid gap-1">{localizedNav.map(({ label, icon: Icon, href }) => <a key={href} href={href} onClick={() => setActive(href)} className={`flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm transition-colors ${active === href ? 'bg-slate-950 font-medium text-white' : 'text-slate-600 hover:bg-slate-100'}`}><Icon />{t(label)}</a>)}</nav></div><Separator /><div className="rounded-xl bg-violet-50 p-4"><Zap className="mb-3 text-violet-600" /><p className="text-sm font-semibold">{t("Objectif du jour")}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{t("Comprendre comment une erreur devient une mise à jour.")}</p></div></div></aside><div className="min-w-0 px-4 py-8 sm:px-6 lg:px-10 lg:py-12"><div className="mx-auto max-w-6xl space-y-16"><section className="relative overflow-hidden rounded-3xl bg-slate-950 px-6 py-10 text-white shadow-xl sm:px-10"><div className="absolute -right-24 -top-24 size-72 rounded-full bg-violet-500/20 blur-3xl" /><div className="absolute -bottom-32 left-1/3 size-80 rounded-full bg-blue-500/15 blur-3xl" /><div className="relative max-w-3xl"><Badge className="mb-5 border-blue-300/30 bg-blue-400/10 text-blue-200 hover:bg-blue-400/10">{t("LABORATOIRE INTERACTIF · 01")}</Badge><h1 className="text-4xl font-bold tracking-tight sm:text-6xl">{t("Comprendre comment les modèles apprennent.")}</h1><p className="mt-5 max-w-2xl text-base leading-7 text-slate-300 sm:text-lg">{t("Une expérience guidée pour passer des équations de rétropropagation à une simulation vivante de descente de gradient.")}</p><div className="mt-7 flex flex-wrap gap-3"><a href="#learn" className="inline-flex h-9 items-center justify-center gap-2 rounded-lg bg-white px-4 text-sm font-medium text-slate-950 shadow-sm transition-colors hover:bg-slate-100">{t("Commencer l’activité")}<ArrowRight /></a><a href="#visualize" className="inline-flex h-9 items-center justify-center rounded-lg border border-slate-600 bg-transparent px-4 text-sm font-medium text-white transition-colors hover:bg-slate-800">{t("Voir le modèle en action")}</a></div></div></section><ManualActivity language={language} onContinue={() => { setManualDone(true); document.getElementById('experiment')?.scrollIntoView({ behavior: 'smooth' }) }} onRestart={() => { setManualDone(false); setHasRun(false); document.getElementById('learn')?.scrollIntoView({ behavior: 'smooth' }) }} /><Card className="border-violet-200 bg-violet-50 shadow-sm"><CardContent className="grid gap-5 p-6 md:grid-cols-2"><div><div className="mb-3 flex items-center gap-2 text-violet-800"><GitBranch /> <span className="font-semibold">{t("Même mécanisme, autre focale")}</span></div><h3 className="text-lg font-bold leading-snug text-slate-950">{t("De 4 paramètres à 2 paramètres")}</h3><p className="mt-2 text-sm leading-6 text-slate-700">{t("Le premier réseau contient un neurone caché sigmoïde et une sortie linéaire. Ici, un neurone linéaire isole le cœur de la descente de gradient : un poids, un biais et des dérivées directes.")}</p></div><div className="grid grid-cols-2 gap-3 text-sm"><div className="rounded-xl border bg-white p-4"><p className="font-semibold text-slate-900">{language === 'fr' ? 'Activité 1' : language === 'en' ? 'Activity 1' : language === 'es' ? 'Actividad 1' : language === 'ar' ? 'النشاط 1' : language === 'hi' ? 'गतिविधि 1' : language === 'tr' ? 'Etkinlik 1' : 'Atividade 1'}</p><p className="mt-2 text-slate-700">{t("1 entrée · sigmoïde cachée")}<br />{t("4 paramètres · chaîne complète")}</p></div><div className="rounded-xl border bg-white p-4"><p className="font-semibold text-slate-900">{language === 'fr' ? 'Activité 2' : language === 'en' ? 'Activity 2' : language === 'es' ? 'Actividad 2' : language === 'ar' ? 'النشاط 2' : language === 'hi' ? 'गतिविधि 2' : language === 'tr' ? 'Etkinlik 2' : 'Atividade 2'}</p><p className="mt-2 text-slate-700">{t("1 neurone linéaire")}<br />{t("2 paramètres · dérivées directes")}</p></div></div></CardContent></Card><CodeLab onRun={run} unlocked={manualDone} language={language} /><TrainingLab history={history} learningRate={learningRate} setLearningRate={v => { setLearningRate(v); setHistory(trainLinear(v, history.length - 1, history[0].w, history[0].b, history[0].x, history[0].target)) }} language={language} /><QuizSection onProgress={setQuizAnswered} /></div></div></div><footer className="border-t bg-white py-8 text-center text-sm text-muted-foreground">Neural Network Learning Lab · {labels.footer}</footer></main></TranslationProvider>
}
